scripts/evaluation_status.py:
"""Show ledger progress without treating partial predictions as quality reports."""

from __future__ import annotations

import argparse
import hashlib
import json
import math
import shlex
import subprocess
from collections import Counter
from datetime import datetime, timezone
from pathlib import Path


def progress(directory: Path, scheduled: int) -> dict:
    identity = None
    for filename in ("run.json", "freeze.json"):
        if (directory / filename).is_file():
            candidate = json.loads((directory / filename).read_text())
            if "document_ids" in candidate:
                identity = candidate
                break
    expected = None
    if identity is not None:
        ids = identity["document_ids"]
        if (not isinstance(ids, list) or not ids or any(not isinstance(id, str) or
                Path(id).name != id or id in (".", "..") for id in ids) or len(set(ids)) != len(ids)):
            raise ValueError("Invalid frozen document schedule")
        expected = {f"{id}.json" for id in ids}
        scheduled = len(expected)
    ledger = json.loads((directory / "completed.json").read_text()) if (directory / "completed.json").exists() else {}
    if not isinstance(ledger, dict) or len(ledger) > scheduled or (expected is not None and set(ledger) - expected):
        raise ValueError("Completion ledger differs from the scheduled documents")
    failed = 0
    failures, timings = Counter(), []
    for name in ledger:
        if Path(name).name != name or not name.endswith(".json"):
            raise ValueError("Unsafe prediction name in completion ledger")
        path = directory / "predictions" / name
        if path.is_symlink() or hashlib.sha256(path.read_bytes()).hexdigest() != ledger[name]:
            raise ValueError("Completed prediction differs from its ledger")
        prediction = json.loads(path.read_text())
        failed += prediction.get("record") is None
        if prediction.get("record") is None:
            failures[prediction.get("failure_type") or "unspecified"] += 1
        seconds = prediction.get("runtime_seconds", {}).get("model")
        if seconds is not None:
            if isinstance(seconds, bool) or not isinstance(seconds, (int, float)) or not math.isfinite(seconds) or seconds < 0:
                raise ValueError("Invalid recorded model timing")
            timings.append(seconds)
    sessions = sorted((directory / "sessions").iterdir()) if (directory / "sessions").exists() else []
    progress_at = datetime.fromtimestamp((directory / "completed.json").stat().st_mtime, timezone.utc).isoformat() if ledger else None
    remaining = scheduled - len(ledger)
    timing_summary = None
    if timings:
        ordered = sorted(timings)
        mean = sum(timings) / len(timings)
        timing_summary = {"calls": len(timings), "total_seconds": round(sum(timings), 3),
                          "mean_seconds": round(mean, 3),
                          "p50_seconds": ordered[math.ceil(.5 * len(ordered)) - 1],
                          "p95_seconds": ordered[math.ceil(.95 * len(ordered)) - 1],
                          "remaining_stage_seconds_estimate": round(mean * remaining) if len(timings) >= 5 and mean > 0 else None,
                          "scope": "Completed per-document stages including failures and any page/repair requests; calls counts documents, not HTTP requests. Saved-OCR model stage only. Remaining-stage estimate uses their mean; excludes startup, interrupted uncommitted attempts, queued receipt stages, reports and human review. Partial sample and changing machine load make it provisional; no completion-time guarantee."}
    return {"completed": len(ledger), "scheduled": scheduled, "remaining": remaining, "failed": failed,
            "failure_types": dict(sorted(failures.items())), "model_stage_timing": timing_summary,
            "schedule_source": "frozen run" if identity is not None else "configured release target",
            "report_written": (directory / "report.json").exists(), "last_ledger_update_utc": progress_at,
            "sessions_without_runtime": [s.name for s in sessions if not (s / "runtime.json").exists()],
            "sessions_with_interruption_observation": [s.name for s in sessions if (s / "interruption.json").is_file()],
            "quality_state": "not audited by this progress command; report existence does not establish verified quality",
            "process_state": "not inspected; missing runtime metadata does not establish a live process"}


def runner_status(launch_path: Path, *, inspect: bool = False) -> dict:
    """Inspect only the recorded coordinator PID; never print process arguments."""
    status = {"state": "not_inspected", "scope": "Coordinator identity only; does not establish child-model health or progress."}
    if not launch_path.is_file():
        return {**status, "state": "launch_missing"}
    launch = json.loads(launch_path.read_text())
    pid, command = launch.get("pid"), launch.get("command")
    if (type(pid) is not int or pid <= 0 or not isinstance(command, list) or len(command) < 2 or
            any(not isinstance(part, str) for part in command) or
            Path(command[1]).name != "complete_release_evaluations.py"):
        raise ValueError("Invalid coordinator launch identity")
    status.update(pid=pid, started_at_utc=launch.get("started_at_utc"))
    if not inspect:
        return status
    try:
        result = subprocess.run(["ps", "-p", str(pid), "-o", "args="], capture_output=True, text=True, timeout=5)
    except (OSError, subprocess.TimeoutExpired):
        return {**status, "state": "inspection_unavailable"}
    if result.returncode == 1 and not result.stdout.strip() and not result.stderr.strip():
        return {**status, "state": "not_running"}
    if result.returncode != 0:
        return {**status, "state": "inspection_unavailable"}
    try:
        actual = shlex.split(result.stdout.strip())
    except ValueError:
        return {**status, "state": "identity_mismatch"}
    executable = Path(command[0]).resolve()
    allowed_executables = {executable}
    # macOS framework Python execs its app binary after the recorded bin launcher.
    # Accept only that binary in the same resolved framework version, never an
    # arbitrary process with a matching interpreter name.
    if executable.parent.name == "bin" and "Python.framework" in executable.parts:
        app_binary = executable.parents[1] / "Resources/Python.app/Contents/MacOS/Python"
        if app_binary.is_file():
            allowed_executables.add(app_binary.resolve())
    matches = len(actual) == len(command) and actual[1:] == command[1:] and Path(actual[0]).resolve() in allowed_executables
    return {**status, "state": "running" if matches else "identity_mismatch",
            "observed_at_utc": datetime.now(timezone.utc).isoformat()}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--invoice", type=Path, default=Path("evals/invoice-model-heldout-2026-10-03"))
    parser.add_argument("--receipts", type=Path, default=Path("evals/cord-heldout-2026-10-03"))
    parser.add_argument("--runner-launch", type=Path, default=Path("artifacts/release-runner-2026-10-03/launch.json"))
    parser.add_argument("--inspect-runner", action="store_true", help="Check the recorded coordinator PID and full identity; process arguments are never printed")
    args = parser.parse_args()
    print(json.dumps({"observed_at_utc": datetime.now(timezone.utc).isoformat(),
                      "runner": runner_status(args.runner_launch, inspect=args.inspect_runner),
                      "invoice_model": progress(args.invoice, 180),
                      "receipt_validation_rules": progress(Path("evals/cord-validation-2026-10-03/ocr-rules"), 100),
                      "receipt_validation_model": progress(args.receipts / "validation-model-12", 12),
                      "receipt_test_rules": progress(args.receipts / "test-rules", 100),
                      "receipt_test_model": progress(args.receipts / "test-model", 100),
                      "receipt_comparison_written": (args.receipts / "comparison.json").exists()}, indent=2))


if __name__ == "__main__":
    main()

scripts/group_memory.py:
"""Native macOS group accounting; never sum nested guest/container observations."""
from __future__ import annotations

import gzip
import json
import math
import re
import subprocess
import tempfile
import threading
import time
from pathlib import Path

from memory_accounting import DarwinFootprint

METHOD = "native-group-footprint-v1"
COUNTERS = ("dirty", "swapped", "clean", "reclaimable", "wired", "regions")
COMPONENTS = {"application", "model", "docker_support", "docker_vm"}
ERROR_REASONS = {
    "Application process unavailable": "application_unavailable",
    "Exactly one associated Docker VM is required": "vm_unavailable",
    "VM backing-store inspection unavailable": "backing_inspection_unavailable",
    "Native group query failed": "native_query_failed",
    "Native inspection is incomplete": "native_inspection_incomplete",
    "Process exited/reused during native query": "process_exited_or_reused",
    "Job ownership database unavailable": "job_registry_unavailable",
}


class AttributionViolation(ValueError):
    """A competing workload invalidates the accounting boundary for the run."""


def require(value, message):
    if not value:
        raise ValueError(message)


def counter(value):
    require(type(value) is int and value >= 0, "Invalid native memory counter")
    return value


def totals(data):
    require(set(data) == set(COUNTERS), "Incomplete native category counters")
    values = {name: counter(data[name]) for name in COUNTERS}
    require(values["swapped"] <= values["dirty"] and
            values["wired"] <= values["dirty"] + values["clean"] + values["reclaimable"], "Inconsistent native subsets")
    return values


def validate_native(data, selection):
    require(data["unit"] == "byte" and data["bytes per unit"] == 1, "Native accounting needs byte units")
    require(data["errors"] == [] and data["warnings"] == [], "Native inspection is incomplete")
    require(type(data["page size"]) is int and data["page size"] > 0, "Invalid native page size")
    identities = {item["pid"]: item for item in selection}
    require(len(identities) == len(selection) and bool(identities), "Duplicate/empty process selection")
    require(all(item["component"] in COMPONENTS and type(item["pid"]) is int and item["pid"] > 0 and
                type(item["start_abstime"]) is int and item["start_abstime"] > 0 for item in selection), "Invalid process identity")
    pids = [item["pid"] for item in data["processes"]]
    require(len(pids) == len(set(pids)) and set(pids) == set(identities), "Native process selection differs")
    for process in data["processes"]:
        counter(process["footprint"])
        current = counter(process["auxiliary"]["phys_footprint"])
        require(counter(process["auxiliary"]["phys_footprint_peak"]) >= current, "Invalid native high-water counter")
        for values in process["categories"].values():
            totals(values)
    for entry in data["shared"]:
        require(bool(entry["pids"]) and set(entry["pids"]) <= set(pids) and
                ("specific_to_pid" not in entry or entry["specific_to_pid"] in entry["pids"]), "Shared mapping has unknown process")
        for values in entry["categories"].values():
            totals(values)
    for values in data["summary"].values():
        totals(values)
    total = totals(data["summary"]["total"])
    require(counter(data["total footprint"]) == total["dirty"], "Native summary footprint differs")
    start, end = data["start_time"], data["end_time"]
    for name in ("mach_absolute_time_ns", "mach_continuous_time_ns", "wall_time_s"):
        require(type(start[name]) in (int, float) and type(end[name]) in (int, float) and
                math.isfinite(start[name]) and math.isfinite(end[name]) and 0 <= start[name] <= end[name], "Invalid native observation window")
    return total


def process_rows():
    raw = subprocess.check_output(["ps", "-axo", "pid=,ppid=,rss=,comm="], text=True, timeout=5)
    return [(int(pid), int(parent), int(rss) * 1024, name)
            for pid, parent, rss, name in (line.strip().split(None, 3) for line in raw.splitlines())]


def descendant_pids(rows, root):
    values = {root}
    for _ in rows:
        added = {pid for pid, parent, _, _ in rows if parent in values}
        if added <= values:
            break
        values |= added
    return values


def docker_vm_association(pid):
    expected = str(Path.home() / "Library/Containers/com.docker.docker/Data/vms/0/data/Docker.raw")
    result = subprocess.run(["/usr/sbin/lsof", "-n", "-Fn", "-p", str(pid)],
                            capture_output=True, text=True, timeout=10, check=False)
    require(result.returncode == 0, "VM backing-store inspection unavailable")
    return any(line == "n" + expected for line in result.stdout.splitlines())


class GroupSampler:
    def __init__(self, application_pid, output, allowed_containers, *, interval=.5):
        self.pid, self.output, self.allowed_containers = application_pid, output, allowed_containers
        self.interval, self.reader = interval, DarwinFootprint()
        self.origin = time.monotonic()
        self.samples, self.errors, self.associations = [], [], {}
        self.stop = threading.Event()
        self.thread = threading.Thread(target=self.run, name="native-group-memory", daemon=True)
        self.closed = False

    def select(self, rows):
        descendants = descendant_pids(rows, self.pid)
        selected = []
        for pid, _, _, name in rows:
            component = None
            if pid in descendants:
                component = "model" if Path(name).name == "llama-server" else "application"
            elif Path(name).name in ("com.docker.backend", "com.docker.virtualization"):
                component = "docker_support"
            elif Path(name).name == "com.apple.Virtualization.VirtualMachine":
                identity = self.reader.read(pid)
                key = (pid, identity["start_abstime"])
                if key not in self.associations:
                    self.associations[key] = docker_vm_association(pid)
                if self.associations[key]:
                    component = "docker_vm"
            if component:
                identity = self.reader.read(pid)
                selected.append({"pid": pid, "start_abstime": identity["start_abstime"], "component": component})
        require(any(item["pid"] == self.pid for item in selected), "Application process unavailable")
        vm_count = sum(item["component"] == "docker_vm" for item in selected)
        if vm_count > 1:
            raise AttributionViolation("Multiple associated Docker VMs")
        require(vm_count == 1, "Exactly one associated Docker VM is required")
        return sorted(selected, key=lambda item: item["pid"])

    def sample(self):
        selected = self.select(process_rows())
        containers = subprocess.check_output(["docker", "ps", "--format", "{{.Names}}"], text=True, timeout=5).splitlines()
        if not set(containers) <= self.allowed_containers():
            raise AttributionViolation("Unrelated container invalidates VM attribution")
        with tempfile.TemporaryDirectory(prefix="docwork-native-footprint-") as temporary:
            path = Path(temporary) / "native.json"
            command = ["/usr/bin/footprint", "--wired", "--swapped", "--sysFootprint", "-f", "bytes", "-j", str(path),
                       *[str(item["pid"]) for item in selected]]
            result = subprocess.run(command, capture_output=True, text=True, timeout=10, check=False)
            require(result.returncode == 0 and path.is_file(), "Native group query failed")
            data = json.loads(path.read_text())
        validate_native(data, selected)
        for item in selected:
            require(self.reader.read(item["pid"])["start_abstime"] == item["start_abstime"], "Process exited/reused during native query")
        return {"elapsed_seconds": time.monotonic() - self.origin, "selection": selected,
                "containers": containers, "native": data}

    def start(self):
        self.thread.start()

    def run(self):
        while not self.stop.is_set():
            try:
                self.samples.append(self.sample())
            except (OSError, ValueError, KeyError, TypeError, subprocess.SubprocessError) as error:
                # Error labels never contain process command arguments/document data.
                self.errors.append({"elapsed_seconds": time.monotonic() - self.origin,
                                    "category": type(error).__name__,
                                    "errno": error.errno if isinstance(error, OSError) else None,
                                    "reason": ERROR_REASONS.get(str(error), "query_or_counter_error")})
            self.stop.wait(self.interval)

    def close(self):
        self.stop.set()
        self.thread.join(timeout=25)
        self.closed = not self.thread.is_alive()
        require(self.closed, "Native group observer did not stop")
        with gzip.open(self.output, "wt", encoding="utf-8") as stream:
            json.dump(self.samples, stream, separators=(",", ":"), allow_nan=False)
        return {"method": METHOD, "artifact": self.output.name, "samples": len(self.samples),
                "application_pid": self.pid,
                "errors": self.errors, "clean_shutdown": self.closed,
                "observation_seconds": time.monotonic() - self.origin}


def summarize(samples):
    require(bool(samples), "No complete native group observations")
    totals_list = []
    peaks = {}
    driver_categories = set()
    models = 0
    for row in samples:
        values = validate_native(row["native"], row["selection"])
        require(sum(item["component"] == "docker_vm" for item in row["selection"]) == 1 and
                any(item["component"] == "application" for item in row["selection"]), "Missing workload/VM boundary")
        identities = {item["pid"]: item for item in row["selection"]}
        models += any(item["component"] == "model" for item in row["selection"])
        for process in row["native"]["processes"]:
            identity = identities[process["pid"]]
            key = (identity["component"], identity["pid"], identity["start_abstime"])
            peaks[key] = max(peaks.get(key, 0), process["auxiliary"]["phys_footprint_peak"])
        driver_categories |= {name for name in row["native"]["summary"]
                              if any(term in name.lower() for term in ("iokit", "graphics", "unmapped", "nofootprint"))}
        totals_list.append(values)
    times = [row["elapsed_seconds"] for row in samples]
    require(all(type(value) in (int, float) and math.isfinite(value) and value >= 0 for value in times) and
            all(left <= right for left, right in zip(times, times[1:])), "Invalid group observation timeline")
    return {"method": METHOD, "complete_samples": len(samples), "model_samples": models,
            "first_sample_seconds": times[0], "last_sample_seconds": times[-1],
            "max_sample_gap_seconds": max((right - left for left, right in zip(times, times[1:])), default=0),
            "max_observed_group_dirty_bytes": max(row["dirty"] for row in totals_list),
            "max_observed_group_swapped_bytes": max(row["swapped"] for row in totals_list),
            "max_observed_accounted_resident_bytes": max(row["dirty"] - row["swapped"] + row["clean"] + row["reclaimable"] for row in totals_list),
            "max_observed_group_accounted_bytes": max(row["dirty"] + row["clean"] + row["reclaimable"] for row in totals_list),
            "max_observed_group_wired_bytes": max(row["wired"] for row in totals_list),
            "process_lifetime_dirty_upper_bound_bytes": sum(peaks.values()),
            "driver_category_names": sorted(driver_categories),
            "limits": "Native dirty/clean/reclaimable mapping categories are de-duplicated across selected user tasks. "
                      "Swapped is a dirty subset charged at original size; wired is not added. Clean excludes globally shared OS cache. "
                      "Docker VM includes guest/kernel/cache/observer; guest/container counters are nested and not added. "
                      "Lifetime dirty upper bound sums maxima across process identities, can include pre-workload Docker use, "
                      "and is not a simultaneous peak or resident-memory bound. Unattributed kernel/driver/other-user services "
                      "and the browser are outside the selected group. Sampled maxima are lower bounds, not continuous peaks."}

scripts/memory_accounting.py:
"""Read-only workload memory counters; guest and host views are never summed.

Darwin uses libproc RUSAGE_INFO_V4 from the public SDK, not task memory dumps.
The bounded observer reads Linux VM counters through the fixed parser image.
"""
from __future__ import annotations

import ctypes
import json
import math
import platform
import re
import subprocess
import threading
import time
import uuid


METHOD = "component-memory-v2"
RUSAGE_FIELDS = (
    "user_time system_time pkg_idle_wkups interrupt_wkups pageins wired_size resident_size phys_footprint "
    "proc_start_abstime proc_exit_abstime child_user_time child_system_time child_pkg_idle_wkups "
    "child_interrupt_wkups child_pageins child_elapsed_abstime diskio_bytesread diskio_byteswritten "
    "cpu_time_qos_default cpu_time_qos_maintenance cpu_time_qos_background cpu_time_qos_utility "
    "cpu_time_qos_legacy cpu_time_qos_user_initiated cpu_time_qos_user_interactive billed_system_time "
    "serviced_system_time logical_writes lifetime_max_phys_footprint instructions cycles billed_energy "
    "serviced_energy interval_max_phys_footprint runnable_time"
).split()


class UsageV4(ctypes.Structure):
    _fields_ = [("uuid", ctypes.c_uint8 * 16), *((name, ctypes.c_uint64) for name in RUSAGE_FIELDS)]


class DarwinFootprint:
    def __init__(self):
        if platform.system() != "Darwin":
            raise OSError("Darwin footprint counters unavailable on this host")
        self.library = ctypes.CDLL("/usr/lib/libproc.dylib", use_errno=True)
        self.library.proc_pid_rusage.argtypes = [ctypes.c_int, ctypes.c_int, ctypes.c_void_p]
        self.library.proc_pid_rusage.restype = ctypes.c_int

    def read(self, pid):
        value = UsageV4()
        if self.library.proc_pid_rusage(pid, 4, ctypes.byref(value)) != 0:
            code = ctypes.get_errno()
            raise OSError(code, "Process footprint unavailable")
        return {"pid": pid, "start_abstime": value.proc_start_abstime,
                "physical_footprint_bytes": value.phys_footprint,
                "lifetime_max_physical_footprint_bytes": value.lifetime_max_phys_footprint,
                "resident_bytes": value.resident_size, "wired_bytes": value.wired_size}


MEMINFO_KEYS = ("MemTotal", "MemFree", "MemAvailable", "Buffers", "Cached", "SReclaimable",
                "Shmem", "Slab", "KernelStack", "PageTables", "SwapTotal", "SwapFree")
OBSERVER_CODE = """
import json, re, time
from pathlib import Path
keys = set(%r)
while True:
    values = {}
    for line in Path('/proc/meminfo').read_text().splitlines():
        match = re.fullmatch(r'([A-Za-z_()]+):\\s+(\\d+) kB', line)
        if match and match[1] in keys:
            values[match[1]] = int(match[2]) * 1024
    print(json.dumps({'guest_uptime_seconds': float(Path('/proc/uptime').read_text().split()[0]),
        'meminfo_bytes': values,
        'observer_memory_current_bytes': int(Path('/sys/fs/cgroup/memory.current').read_text()),
        'observer_memory_peak_bytes': int(Path('/sys/fs/cgroup/memory.peak').read_text())}), flush=True)
    time.sleep(.25)
""" % (MEMINFO_KEYS,)


def validate_guest(row):
    if set(row["meminfo_bytes"]) != set(MEMINFO_KEYS):
        raise ValueError("Guest VM memory counters incomplete")
    for name, value in row["meminfo_bytes"].items():
        if type(value) is not int or value < 0:
            raise ValueError(f"Invalid guest counter: {name}")
    for field in ("observer_memory_current_bytes", "observer_memory_peak_bytes"):
        if type(row[field]) is not int or row[field] < 0:
            raise ValueError("Invalid observer memory counter")
    values = row["meminfo_bytes"]
    if (values["MemTotal"] <= 0 or values["MemAvailable"] > values["MemTotal"] or
            values["MemFree"] > values["MemTotal"] or values["SwapFree"] > values["SwapTotal"] or
            row["observer_memory_peak_bytes"] < row["observer_memory_current_bytes"] or
            type(row["guest_uptime_seconds"]) not in (int, float) or
            not math.isfinite(row["guest_uptime_seconds"]) or row["guest_uptime_seconds"] < 0):
        raise ValueError("Inconsistent guest VM memory counters")
    return row


class GuestObserver:
    def __init__(self, image, origin):
        if not re.fullmatch(r"sha256:[0-9a-f]{64}", image):
            raise ValueError("Observer needs the immutable frozen parser image")
        self.name = "docwork-memory-" + uuid.uuid4().hex
        self.image, self.origin = image, origin
        self.samples, self.errors = [], 0
        self.process = self.thread = None
        self.clean_shutdown = False
        self.cleanup_failure = None
        self.creation_attempted = False
        self.early_exit = False

    def start(self):
        self.creation_attempted = True
        subprocess.run([
            "docker", "create", "--pull", "never", "--name", self.name, "--network", "none",
            "--read-only", "--user", "65534:65534", "--cap-drop", "ALL",
            "--security-opt", "no-new-privileges", "--memory", "32m", "--memory-swap", "32m",
            "--cpus", "0.1", "--pids-limit", "16", "--entrypoint", "python",
            self.image, "-u", "-c", OBSERVER_CODE], capture_output=True, text=True, check=True, timeout=60)
        self.process = subprocess.Popen(["docker", "start", "--attach", self.name],
                                        stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, text=True)
        self.thread = threading.Thread(target=self.receive, daemon=True)
        self.thread.start()

    def receive(self):
        for line in self.process.stdout:
            try:
                row = validate_guest(json.loads(line))
                self.samples.append({"received_elapsed_seconds": round(time.monotonic() - self.origin, 6), **row})
            except (ValueError, KeyError, TypeError):
                self.errors += 1

    def close(self):
        if self.creation_attempted:
            self.early_exit = self.process is not None and self.process.poll() is not None
            try:
                # Signal only the named observer we created. No shell or daemon mounts.
                subprocess.run(["docker", "rm", "--force", self.name], capture_output=True, timeout=15, check=True)
                if self.process is not None:
                    self.process.wait(timeout=15)
                inspected = subprocess.run(["docker", "inspect", self.name], capture_output=True, text=True, timeout=15)
                self.clean_shutdown = (inspected.returncode == 1 and
                                       "no such" in inspected.stderr.lower() and bool(self.samples) and not self.early_exit)
            except (OSError, subprocess.SubprocessError) as error:
                self.errors += 1
                self.cleanup_failure = type(error).__name__
            if self.process is not None:
                if self.process.poll() is None:
                    self.process.kill()
                    self.process.wait(timeout=5)
                if self.thread is not None:
                    self.thread.join(timeout=5)
                    if self.thread.is_alive():
                        self.errors += 1
                self.process.stdout.close()
        return {"samples": self.samples, "sampling_errors": self.errors, "clean_shutdown": self.clean_shutdown,
                "cleanup_failure": self.cleanup_failure,
                "early_exit": self.early_exit,
                "scope": "Whole Linux VM meminfo, including daemon/kernel/cache and a bounded measurement observer; "
                         "parser working sets are nested. Guest occupancy is not host VM residency or app-exclusive use."}


def validate_process(row):
    if row["component"] not in ("application", "model", "docker_backend"):
        raise ValueError("Unknown footprint component")
    for name in ("pid", "start_abstime"):
        if type(row[name]) is not int or row[name] <= 0:
            raise ValueError("Unusable process identity")
    for name in ("physical_footprint_bytes", "lifetime_max_physical_footprint_bytes", "resident_bytes", "wired_bytes"):
        if type(row[name]) is not int or row[name] < 0:
            raise ValueError("Invalid physical-footprint counter")
    if row["lifetime_max_physical_footprint_bytes"] < row["physical_footprint_bytes"]:
        raise ValueError("Process high-water counter below current footprint")
    return row


def physical_sample(rows, descendants, reader):
    selected = {pid: "model" if "llama-server" in name else "application"
                for pid, _, _, name in rows if pid in descendants}
    selected.update({pid: "docker_backend" for pid, _, _, name in rows if "com.docker.backend" in name})
    values, errors = [], []
    for pid, component in sorted(selected.items()):
        try:
            value = reader.read(pid)
            if value["pid"] != pid:
                raise ValueError("Unusable process identity")
            values.append(validate_process({"component": component, **value}))
        except (OSError, ValueError, KeyError, TypeError):
            errors.append({"pid": pid, "component": component, "category": "unavailable_or_exited"})
    return {"processes": values, "errors": errors}


def summarize_memory(memories):
    components = {}
    for component in ("application", "model", "docker_backend"):
        samples, identities = [], {}
        for memory in memories:
            for sample in memory["host_samples"]:
                for row in sample.get("physical_footprint", {}).get("processes", []):
                    validate_process(row)
                    if row["component"] != component:
                        continue
                    samples.append(row["physical_footprint_bytes"])
                    key = (row["pid"], row["start_abstime"])
                    identities[key] = max(identities.get(key, 0), row["lifetime_max_physical_footprint_bytes"])
        components[component] = {"process_observations": len(samples), "process_identities": len(identities),
            "max_observed_single_process_footprint_bytes": max(samples, default=None),
            "max_observed_single_process_lifetime_high_water_bytes": max(identities.values(), default=None)}
    guests = [row for memory in memories for row in memory.get("guest_vm", {}).get("samples", [])]
    for row in guests:
        validate_guest(row)
    return {"method": METHOD, "components": components, "guest_observations": len(guests),
            "guest_vm_max_used_excluding_free_bytes": max((row["meminfo_bytes"]["MemTotal"] -
                row["meminfo_bytes"]["MemFree"] for row in guests), default=None),
            "guest_vm_max_used_excluding_available_bytes": max((row["meminfo_bytes"]["MemTotal"] -
                row["meminfo_bytes"]["MemAvailable"] for row in guests), default=None),
            "observer_max_cgroup_peak_bytes": max((row["observer_memory_peak_bytes"] for row in guests), default=None),
            "process_read_errors": sum(len(row.get("physical_footprint", {}).get("errors", []))
                for memory in memories for row in memory["host_samples"]),
            "guest_sampling_errors": sum(memory.get("guest_vm", {}).get("sampling_errors", 0) for memory in memories),
            "total_memory_acceptance": "pending: host VM residency/driver ownership and application-exclusive union "
                                       "are not established; guest and host observations are not summed",
            "limitations": "Single-process high-water counters include lifetime before observation, especially Docker. "
                           "They are not simultaneous totals or whole-workload peaks. Clean file-backed residency is "
                           "reported separately by RSS; footprint includes charged compressed/IOKit memory. Sampling "
                           "may miss short-lived processes and peaks. Guest occupancy includes shared VM overhead/cache."}

